import test from 'node:test';
import assert from 'node:assert/strict';
import {create,choose,project,replayPolicy,validate,render,describe} from './model.js';
test('initial agreement comes from differing explicit rules, not identical rules',()=>{const s=create(),r=project(s);assert.deepEqual(r.actions,['continue']);assert.equal(new Set(s.rules.map(rule=>rule.priority)).size,3);assert.ok(!Object.hasOwn(r,'score'));});
test('a selected disturbance changes no information until revealed, then reaches its named recipient',()=>{const s=create();s.event='delay';assert.deepEqual(project(s).actions,['continue']);s.revealed=true;const r=project(s);assert.deepEqual(r.people.map(p=>p.action),['continue','narrow','continue']);assert.equal(r.people[1].evidence.delay,7);assert.equal(r.people[0].evidence.delay,0);assert.equal(r.people[2].evidence.delay,0);});
test('shared evidence changes readings without silently changing decision rules',()=>{const s=create();s.event='delay';s.revealed=true;s.shared.delay=true;const r=project(s);assert.deepEqual(r.people.map(p=>p.evidence.delay),[7,7,7]);assert.deepEqual(r.people.map(p=>p.action),['continue','narrow','narrow']);assert.equal(r.people[0].rule.delay,10);});
test('first matching condition wins and equality keeps the current plan',()=>{const evidence={demand:25,risk:4,delay:7},limits={demand:40,risk:0,delay:5};assert.equal(choose(evidence,{...limits,priority:'safety'}).action,'pause');assert.equal(choose(evidence,{...limits,priority:'evidence'}).action,'test');assert.equal(choose(evidence,{...limits,priority:'delivery'}).action,'narrow');assert.equal(choose(limits,{...limits,priority:'safety'}).action,'continue');});
test('joint boundaries request review while independent remits allow different actions',()=>{const s=create();s.event='delay';s.revealed=true;assert.match(project(s).disposition,/unresolved conflict/);s.scope='joint';assert.match(project(s).disposition,/joint review/);s.scenario='local';s.scope='local';assert.match(project(s).disposition,/separate remits/);});
test('a shared principle can produce different agreement without being awarded a goodness score',()=>{const s=create();s.event='risk';s.revealed=true;s.shared={risk:true,demand:true,delay:true};s.principle='safety';assert.deepEqual(project(s).actions,['pause']);s.principle='evidence';assert.deepEqual(project(s).actions,['test']);});
test('small disturbances need not split an agreement',()=>{for(const event of ['delay','demand','risk']){const s=create('rehearsal');s.event=event;s.revealed=true;assert.deepEqual(project(s).actions,['continue']);}});
test('pinned comparison replays policy against the current beliefs and disturbance',()=>{const s=create('local');s.event='delay';s.revealed=true;const pin=create();pin.shared.delay=true;pin.principle='delivery';const before=JSON.stringify([s,pin]),r=replayPolicy(s,pin);assert.equal(r.scenario.name,project(s).scenario.name);assert.deepEqual(r.actions,['narrow']);assert.equal(JSON.stringify([s,pin]),before);});
test('native validation rejects missing, oversized and unknown fields',()=>{for(const alter of [s=>s.extra=true,s=>s.beliefs[0].demand=101,s=>s.rules[0].priority='personality',s=>s.shared.risk='yes',s=>s.rules.push(s.rules[0]),s=>delete s.revealed]){const s=create();alter(s);assert.throws(()=>validate(s));}});
test('article render and exported reasoning use the native projection',()=>{const s=create();s.event='delay';s.revealed=true;const r=project(s);for(const width of [320,390,900]){const view=render(s,{width});assert.equal(view.summary,r.disposition);assert.match(view.svg,/Reduce the scope/);assert.ok(!view.svg.includes('NaN'));}assert.match(describe(s),/7 > 2 is true/);});
test('the initial-state article explanation respects edited starting beliefs',()=>{const s=create();s.beliefs[0].demand=10;const view=render(s);assert.match(view.svg,/Run a small test/);assert.doesNotMatch(view.svg,/Initial plan: continue/);});
